// Constructor
ARCOMMANDS_Decoder_t* ARCOMMANDS_Decoder_NewDecoder (eARCOMMANDS_DECODER_ERROR *error)
{
    ARCOMMANDS_Decoder_t *decoder = NULL;
    int err = 0;

    decoder = calloc(1, sizeof(*decoder));
    if (decoder == NULL)
        goto end;

    err = ARSAL_Mutex_Init (&decoder->mutex);
    if (err != 0) {
        free(decoder);
        decoder = NULL;
    }

end:
    if (error)
        *error = decoder ? ARCOMMANDS_DECODER_OK : ARCOMMANDS_DECODER_ERROR;

    return decoder;
}

// Destructor
void ARCOMMANDS_Decoder_DeleteDecoder (ARCOMMANDS_Decoder_t **decoder)
{
    if (decoder && (*decoder)) {
        ARSAL_Mutex_Destroy(&(*decoder)->mutex);
        free(*decoder);
        *decoder = NULL;
    }
}

// CALLBACK VARIABLES + SETTERS

static ARSAL_Mutex_t ARCOMMANDS_Decoder_Mutex;
static int ARCOMMANDS_Decoder_IsInit = 0;
static int ARCOMMANDS_Decoder_Init (void)
{
    if ((ARCOMMANDS_Decoder_IsInit == 0) &&
        (ARSAL_Mutex_Init (&ARCOMMANDS_Decoder_Mutex) == 0))
    {
        ARCOMMANDS_Decoder_IsInit = 1;
    } // No else --> Do nothing if already initialized
    return ARCOMMANDS_Decoder_IsInit;
}

// Feature generic

void ARCOMMANDS_Decoder_SetGenericDefaultCb (ARCOMMANDS_Decoder_t *decoder, ARCOMMANDS_Decoder_GenericDefaultCallback_t callback, void *custom)
{
    if (!decoder)
        return;

    ARSAL_Mutex_Lock (&decoder->mutex);
    decoder->GenericDefaultCallback = callback;
    decoder->GenericDefaultCustom = custom;
    ARSAL_Mutex_Unlock (&decoder->mutex);
}

static ARCOMMANDS_Decoder_GenericDefaultCallback_t ARCOMMANDS_Decoder_GenericDefaultCb = NULL;
static void *ARCOMMANDS_Decoder_GenericDefaultCustom = NULL;
void ARCOMMANDS_Decoder_SetGenericDefaultCallback (ARCOMMANDS_Decoder_GenericDefaultCallback_t callback, void *custom)
{
    if (ARCOMMANDS_Decoder_Init () == 1)
    {
        ARSAL_Mutex_Lock (&ARCOMMANDS_Decoder_Mutex);
        ARCOMMANDS_Decoder_GenericDefaultCb = callback;
        ARCOMMANDS_Decoder_GenericDefaultCustom = custom;
        ARSAL_Mutex_Unlock (&ARCOMMANDS_Decoder_Mutex);
    } // No else --> do nothing if library can not be initialized
}
eARCOMMANDS_DECODER_ERROR
ARCOMMANDS_Decoder_DecodeGenericSetDroneSettings (ARCOMMANDS_Decoder_t *decoder, ARCOMMANDS_Generic_DroneSettings_t * multisetting)
{
    eARCOMMANDS_DECODER_ERROR retVal = ARCOMMANDS_DECODER_OK;
    if ((NULL == decoder) ||
        (NULL == multisetting))
    {
        retVal = ARCOMMANDS_DECODER_ERROR;
    } // No else --> Arg check
    
    if (retVal == ARCOMMANDS_DECODER_OK)
    {
        if ((multisetting->MaxAltitude.isSet) && (decoder->ARDrone3PilotingSettingsMaxAltitudeCallback)) {
            decoder->ARDrone3PilotingSettingsMaxAltitudeCallback (multisetting->MaxAltitude.current, decoder->ARDrone3PilotingSettingsMaxAltitudeCustom);
        }
        if ((multisetting->MaxTilt.isSet) && (decoder->ARDrone3PilotingSettingsMaxTiltCallback)) {
            decoder->ARDrone3PilotingSettingsMaxTiltCallback (multisetting->MaxTilt.current, decoder->ARDrone3PilotingSettingsMaxTiltCustom);
        }
        if ((multisetting->MaxDistance.isSet) && (decoder->ARDrone3PilotingSettingsMaxDistanceCallback)) {
            decoder->ARDrone3PilotingSettingsMaxDistanceCallback (multisetting->MaxDistance.value, decoder->ARDrone3PilotingSettingsMaxDistanceCustom);
        }
        if ((multisetting->NoFlyOverMaxDistance.isSet) && (decoder->ARDrone3PilotingSettingsNoFlyOverMaxDistanceCallback)) {
            decoder->ARDrone3PilotingSettingsNoFlyOverMaxDistanceCallback (multisetting->NoFlyOverMaxDistance.shouldNotFlyOver, decoder->ARDrone3PilotingSettingsNoFlyOverMaxDistanceCustom);
        }
        if ((multisetting->MaxVerticalSpeed.isSet) && (decoder->ARDrone3SpeedSettingsMaxVerticalSpeedCallback)) {
            decoder->ARDrone3SpeedSettingsMaxVerticalSpeedCallback (multisetting->MaxVerticalSpeed.current, decoder->ARDrone3SpeedSettingsMaxVerticalSpeedCustom);
        }
        if ((multisetting->MaxRotationSpeed.isSet) && (decoder->ARDrone3SpeedSettingsMaxRotationSpeedCallback)) {
            decoder->ARDrone3SpeedSettingsMaxRotationSpeedCallback (multisetting->MaxRotationSpeed.current, decoder->ARDrone3SpeedSettingsMaxRotationSpeedCustom);
        }
        if ((multisetting->MaxPitchRollRotationSpeed.isSet) && (decoder->ARDrone3SpeedSettingsMaxPitchRollRotationSpeedCallback)) {
            decoder->ARDrone3SpeedSettingsMaxPitchRollRotationSpeedCallback (multisetting->MaxPitchRollRotationSpeed.current, decoder->ARDrone3SpeedSettingsMaxPitchRollRotationSpeedCustom);
        }
        if ((multisetting->ReturnHomeDelay.isSet) && (decoder->ARDrone3GPSSettingsReturnHomeDelayCallback)) {
            decoder->ARDrone3GPSSettingsReturnHomeDelayCallback (multisetting->ReturnHomeDelay.delay, decoder->ARDrone3GPSSettingsReturnHomeDelayCustom);
        }
        if ((multisetting->HomeType.isSet) && (decoder->ARDrone3GPSSettingsHomeTypeCallback)) {
            decoder->ARDrone3GPSSettingsHomeTypeCallback (multisetting->HomeType.type, decoder->ARDrone3GPSSettingsHomeTypeCustom);
        }
        if ((multisetting->VideoStabilizationMode.isSet) && (decoder->ARDrone3PictureSettingsVideoStabilizationModeCallback)) {
            decoder->ARDrone3PictureSettingsVideoStabilizationModeCallback (multisetting->VideoStabilizationMode.mode, decoder->ARDrone3PictureSettingsVideoStabilizationModeCustom);
        }
        if ((multisetting->BankedTurn.isSet) && (decoder->ARDrone3PilotingSettingsBankedTurnCallback)) {
            decoder->ARDrone3PilotingSettingsBankedTurnCallback (multisetting->BankedTurn.value, decoder->ARDrone3PilotingSettingsBankedTurnCustom);
        }
    }
    return retVal;
}

void ARCOMMANDS_Decoder_SetGenericSetDroneSettingsCb (ARCOMMANDS_Decoder_t *decoder, ARCOMMANDS_Decoder_GenericSetDroneSettingsCallback_t callback, void *custom)
{
    if (!decoder)
        return;

    ARSAL_Mutex_Lock (&decoder->mutex);
    decoder->GenericSetDroneSettingsCallback = callback;
    decoder->GenericSetDroneSettingsCustom = custom;
    ARSAL_Mutex_Unlock (&decoder->mutex);
}

static ARCOMMANDS_Decoder_GenericSetDroneSettingsCallback_t ARCOMMANDS_Decoder_GenericSetDroneSettingsCb = NULL;
static void *ARCOMMANDS_Decoder_GenericSetDroneSettingsCustom = NULL;
void ARCOMMANDS_Decoder_SetGenericSetDroneSettingsCallback (ARCOMMANDS_Decoder_GenericSetDroneSettingsCallback_t callback, void *custom)
{
    if (ARCOMMANDS_Decoder_Init () == 1)
    {
        ARSAL_Mutex_Lock (&ARCOMMANDS_Decoder_Mutex);
        ARCOMMANDS_Decoder_GenericSetDroneSettingsCb = callback;
        ARCOMMANDS_Decoder_GenericSetDroneSettingsCustom = custom;
        ARSAL_Mutex_Unlock (&ARCOMMANDS_Decoder_Mutex);
    } // No else --> do nothing if library can not be initialized
}
eARCOMMANDS_DECODER_ERROR
ARCOMMANDS_Decoder_DecodeGenericDroneSettingsChanged (ARCOMMANDS_Decoder_t *decoder, ARCOMMANDS_Generic_DroneSettingsChanged_t * multisetting)
{
    eARCOMMANDS_DECODER_ERROR retVal = ARCOMMANDS_DECODER_OK;
    if ((NULL == decoder) ||
        (NULL == multisetting))
    {
        retVal = ARCOMMANDS_DECODER_ERROR;
    } // No else --> Arg check
    
    if (retVal == ARCOMMANDS_DECODER_OK)
    {
        if ((multisetting->MaxAltitudeChanged.isSet) && (decoder->ARDrone3PilotingSettingsStateMaxAltitudeChangedCallback)) {
            decoder->ARDrone3PilotingSettingsStateMaxAltitudeChangedCallback (multisetting->MaxAltitudeChanged.current, multisetting->MaxAltitudeChanged.min, multisetting->MaxAltitudeChanged.max, decoder->ARDrone3PilotingSettingsStateMaxAltitudeChangedCustom);
        }
        if ((multisetting->MaxTiltChanged.isSet) && (decoder->ARDrone3PilotingSettingsStateMaxTiltChangedCallback)) {
            decoder->ARDrone3PilotingSettingsStateMaxTiltChangedCallback (multisetting->MaxTiltChanged.current, multisetting->MaxTiltChanged.min, multisetting->MaxTiltChanged.max, decoder->ARDrone3PilotingSettingsStateMaxTiltChangedCustom);
        }
        if ((multisetting->MaxDistanceChanged.isSet) && (decoder->ARDrone3PilotingSettingsStateMaxDistanceChangedCallback)) {
            decoder->ARDrone3PilotingSettingsStateMaxDistanceChangedCallback (multisetting->MaxDistanceChanged.current, multisetting->MaxDistanceChanged.min, multisetting->MaxDistanceChanged.max, decoder->ARDrone3PilotingSettingsStateMaxDistanceChangedCustom);
        }
        if ((multisetting->NoFlyOverMaxDistanceChanged.isSet) && (decoder->ARDrone3PilotingSettingsStateNoFlyOverMaxDistanceChangedCallback)) {
            decoder->ARDrone3PilotingSettingsStateNoFlyOverMaxDistanceChangedCallback (multisetting->NoFlyOverMaxDistanceChanged.shouldNotFlyOver, decoder->ARDrone3PilotingSettingsStateNoFlyOverMaxDistanceChangedCustom);
        }
        if ((multisetting->MaxVerticalSpeedChanged.isSet) && (decoder->ARDrone3SpeedSettingsStateMaxVerticalSpeedChangedCallback)) {
            decoder->ARDrone3SpeedSettingsStateMaxVerticalSpeedChangedCallback (multisetting->MaxVerticalSpeedChanged.current, multisetting->MaxVerticalSpeedChanged.min, multisetting->MaxVerticalSpeedChanged.max, decoder->ARDrone3SpeedSettingsStateMaxVerticalSpeedChangedCustom);
        }
        if ((multisetting->MaxRotationSpeedChanged.isSet) && (decoder->ARDrone3SpeedSettingsStateMaxRotationSpeedChangedCallback)) {
            decoder->ARDrone3SpeedSettingsStateMaxRotationSpeedChangedCallback (multisetting->MaxRotationSpeedChanged.current, multisetting->MaxRotationSpeedChanged.min, multisetting->MaxRotationSpeedChanged.max, decoder->ARDrone3SpeedSettingsStateMaxRotationSpeedChangedCustom);
        }
        if ((multisetting->MaxPitchRollRotationSpeedChanged.isSet) && (decoder->ARDrone3SpeedSettingsStateMaxPitchRollRotationSpeedChangedCallback)) {
            decoder->ARDrone3SpeedSettingsStateMaxPitchRollRotationSpeedChangedCallback (multisetting->MaxPitchRollRotationSpeedChanged.current, multisetting->MaxPitchRollRotationSpeedChanged.min, multisetting->MaxPitchRollRotationSpeedChanged.max, decoder->ARDrone3SpeedSettingsStateMaxPitchRollRotationSpeedChangedCustom);
        }
        if ((multisetting->ReturnHomeDelayChanged.isSet) && (decoder->ARDrone3GPSSettingsStateReturnHomeDelayChangedCallback)) {
            decoder->ARDrone3GPSSettingsStateReturnHomeDelayChangedCallback (multisetting->ReturnHomeDelayChanged.delay, decoder->ARDrone3GPSSettingsStateReturnHomeDelayChangedCustom);
        }
        if ((multisetting->HomeTypeChanged.isSet) && (decoder->ARDrone3GPSSettingsStateHomeTypeChangedCallback)) {
            decoder->ARDrone3GPSSettingsStateHomeTypeChangedCallback (multisetting->HomeTypeChanged.type, decoder->ARDrone3GPSSettingsStateHomeTypeChangedCustom);
        }
        if ((multisetting->VideoStabilizationModeChanged.isSet) && (decoder->ARDrone3PictureSettingsStateVideoStabilizationModeChangedCallback)) {
            decoder->ARDrone3PictureSettingsStateVideoStabilizationModeChangedCallback (multisetting->VideoStabilizationModeChanged.mode, decoder->ARDrone3PictureSettingsStateVideoStabilizationModeChangedCustom);
        }
        if ((multisetting->BankedTurnChanged.isSet) && (decoder->ARDrone3PilotingSettingsStateBankedTurnChangedCallback)) {
            decoder->ARDrone3PilotingSettingsStateBankedTurnChangedCallback (multisetting->BankedTurnChanged.state, decoder->ARDrone3PilotingSettingsStateBankedTurnChangedCustom);
        }
    }
    return retVal;
}

