static eARCOMMANDS_DECODER_ERROR ARCOMMANDS_Decoder_GenericSetDroneSettingsDecodeArgs (const uint8_t *buffer, int32_t buffLen, int32_t *offset, ARCOMMANDS_Generic_DroneSettings_t *_settings)
{
    eARCOMMANDS_DECODER_ERROR retVal = ARCOMMANDS_DECODER_OK;
    int32_t error = 0;
    eARCOMMANDS_ID_FEATURE commandFeature = -1;
    int commandClass = -1;
    int commandId = -1;
    uint16_t multisetSize = 0;
    int32_t multisetEnd = 0;
    uint16_t cmdSize = 0;

    if ((NULL == buffer) ||
        (NULL == _settings))
    {
        retVal = ARCOMMANDS_DECODER_ERROR;
    } // No else --> Arg check

    if (retVal == ARCOMMANDS_DECODER_OK)
    {
        memset(_settings, 0, sizeof(*_settings));
        multisetSize = ARCOMMANDS_ReadWrite_Read16FromBuffer (buffer, buffLen, offset, &error);
        if (error == 1)
        {
            retVal = ARCOMMANDS_DECODER_ERROR_NOT_ENOUGH_DATA;
        } // No else --> Do not modify retVal if read went fine
    } // No else --> Processing block

    if (retVal == ARCOMMANDS_DECODER_OK)
    {
        multisetEnd = *offset + multisetSize;
        cmdSize = ARCOMMANDS_ReadWrite_Read16FromBuffer (buffer, buffLen, offset, &error);
        if (error == 1)
        {
            retVal = ARCOMMANDS_DECODER_ERROR_NOT_ENOUGH_DATA;
        } // No else --> Do not modify retVal if read went fine
    } // No else --> Processing block

    while ((retVal == ARCOMMANDS_DECODER_OK) &&
           (*offset < multisetEnd))
    {
        if (retVal == ARCOMMANDS_DECODER_OK)
        {
            commandFeature = ARCOMMANDS_ReadWrite_Read8FromBuffer (buffer, buffLen, offset, &error);
            if (error == 1)
            {
                retVal = ARCOMMANDS_DECODER_ERROR_NOT_ENOUGH_DATA;
            } // No else --> Do not modify retVal if read went fine
        } // No else --> Processing block

        if (retVal == ARCOMMANDS_DECODER_OK)
        {
            commandClass = ARCOMMANDS_ReadWrite_Read8FromBuffer (buffer, buffLen, offset, &error);
            if (error == 1)
            {
                retVal = ARCOMMANDS_DECODER_ERROR_NOT_ENOUGH_DATA;
            } // No else --> Do not modify retVal if read went fine
        } // No else --> Processing block

        if (retVal == ARCOMMANDS_DECODER_OK)
        {
            commandId = ARCOMMANDS_ReadWrite_Read16FromBuffer (buffer, buffLen, offset, &error);
            if (error == 1)
            {
                retVal = ARCOMMANDS_DECODER_ERROR_NOT_ENOUGH_DATA;
            } // No else --> Do not modify retVal if read went fine
        } // No else --> Processing block

        if (retVal == ARCOMMANDS_DECODER_OK)
        {
            switch (commandFeature)
            {
            case ARCOMMANDS_ID_FEATURE_ARDRONE3:
                switch (commandClass)
                {
                case ARCOMMANDS_ID_ARDRONE3_CLASS_GPSSETTINGS:
                    switch (commandId)
                    {
                    case ARCOMMANDS_ID_ARDRONE3_GPSSETTINGS_CMD_RETURNHOMEDELAY:
                        retVal = ARCOMMANDS_Decoder_ARDrone3GPSSettingsReturnHomeDelayDecodeArgs(buffer, buffLen, offset, &_settings->ReturnHomeDelay.delay);
                        if (retVal == ARCOMMANDS_DECODER_OK)
                        {
                            _settings->ReturnHomeDelay.isSet = 1;
                        }
                        break;
                    case ARCOMMANDS_ID_ARDRONE3_GPSSETTINGS_CMD_HOMETYPE:
                        retVal = ARCOMMANDS_Decoder_ARDrone3GPSSettingsHomeTypeDecodeArgs(buffer, buffLen, offset, &_settings->HomeType.type);
                        if (retVal == ARCOMMANDS_DECODER_OK)
                        {
                            _settings->HomeType.isSet = 1;
                        }
                        break;
                    default:
                        // Command unknown
                        *offset += cmdSize;
                       break;
                    }
                    break;
                case ARCOMMANDS_ID_ARDRONE3_CLASS_PICTURESETTINGS:
                    switch (commandId)
                    {
                    case ARCOMMANDS_ID_ARDRONE3_PICTURESETTINGS_CMD_VIDEOSTABILIZATIONMODE:
                        retVal = ARCOMMANDS_Decoder_ARDrone3PictureSettingsVideoStabilizationModeDecodeArgs(buffer, buffLen, offset, &_settings->VideoStabilizationMode.mode);
                        if (retVal == ARCOMMANDS_DECODER_OK)
                        {
                            _settings->VideoStabilizationMode.isSet = 1;
                        }
                        break;
                    default:
                        // Command unknown
                        *offset += cmdSize;
                       break;
                    }
                    break;
                case ARCOMMANDS_ID_ARDRONE3_CLASS_PILOTINGSETTINGS:
                    switch (commandId)
                    {
                    case ARCOMMANDS_ID_ARDRONE3_PILOTINGSETTINGS_CMD_MAXALTITUDE:
                        retVal = ARCOMMANDS_Decoder_ARDrone3PilotingSettingsMaxAltitudeDecodeArgs(buffer, buffLen, offset, &_settings->MaxAltitude.current);
                        if (retVal == ARCOMMANDS_DECODER_OK)
                        {
                            _settings->MaxAltitude.isSet = 1;
                        }
                        break;
                    case ARCOMMANDS_ID_ARDRONE3_PILOTINGSETTINGS_CMD_MAXTILT:
                        retVal = ARCOMMANDS_Decoder_ARDrone3PilotingSettingsMaxTiltDecodeArgs(buffer, buffLen, offset, &_settings->MaxTilt.current);
                        if (retVal == ARCOMMANDS_DECODER_OK)
                        {
                            _settings->MaxTilt.isSet = 1;
                        }
                        break;
                    case ARCOMMANDS_ID_ARDRONE3_PILOTINGSETTINGS_CMD_MAXDISTANCE:
                        retVal = ARCOMMANDS_Decoder_ARDrone3PilotingSettingsMaxDistanceDecodeArgs(buffer, buffLen, offset, &_settings->MaxDistance.value);
                        if (retVal == ARCOMMANDS_DECODER_OK)
                        {
                            _settings->MaxDistance.isSet = 1;
                        }
                        break;
                    case ARCOMMANDS_ID_ARDRONE3_PILOTINGSETTINGS_CMD_NOFLYOVERMAXDISTANCE:
                        retVal = ARCOMMANDS_Decoder_ARDrone3PilotingSettingsNoFlyOverMaxDistanceDecodeArgs(buffer, buffLen, offset, &_settings->NoFlyOverMaxDistance.shouldNotFlyOver);
                        if (retVal == ARCOMMANDS_DECODER_OK)
                        {
                            _settings->NoFlyOverMaxDistance.isSet = 1;
                        }
                        break;
                    case ARCOMMANDS_ID_ARDRONE3_PILOTINGSETTINGS_CMD_BANKEDTURN:
                        retVal = ARCOMMANDS_Decoder_ARDrone3PilotingSettingsBankedTurnDecodeArgs(buffer, buffLen, offset, &_settings->BankedTurn.value);
                        if (retVal == ARCOMMANDS_DECODER_OK)
                        {
                            _settings->BankedTurn.isSet = 1;
                        }
                        break;
                    default:
                        // Command unknown
                        *offset += cmdSize;
                       break;
                    }
                    break;
                case ARCOMMANDS_ID_ARDRONE3_CLASS_SPEEDSETTINGS:
                    switch (commandId)
                    {
                    case ARCOMMANDS_ID_ARDRONE3_SPEEDSETTINGS_CMD_MAXVERTICALSPEED:
                        retVal = ARCOMMANDS_Decoder_ARDrone3SpeedSettingsMaxVerticalSpeedDecodeArgs(buffer, buffLen, offset, &_settings->MaxVerticalSpeed.current);
                        if (retVal == ARCOMMANDS_DECODER_OK)
                        {
                            _settings->MaxVerticalSpeed.isSet = 1;
                        }
                        break;
                    case ARCOMMANDS_ID_ARDRONE3_SPEEDSETTINGS_CMD_MAXROTATIONSPEED:
                        retVal = ARCOMMANDS_Decoder_ARDrone3SpeedSettingsMaxRotationSpeedDecodeArgs(buffer, buffLen, offset, &_settings->MaxRotationSpeed.current);
                        if (retVal == ARCOMMANDS_DECODER_OK)
                        {
                            _settings->MaxRotationSpeed.isSet = 1;
                        }
                        break;
                    case ARCOMMANDS_ID_ARDRONE3_SPEEDSETTINGS_CMD_MAXPITCHROLLROTATIONSPEED:
                        retVal = ARCOMMANDS_Decoder_ARDrone3SpeedSettingsMaxPitchRollRotationSpeedDecodeArgs(buffer, buffLen, offset, &_settings->MaxPitchRollRotationSpeed.current);
                        if (retVal == ARCOMMANDS_DECODER_OK)
                        {
                            _settings->MaxPitchRollRotationSpeed.isSet = 1;
                        }
                        break;
                    default:
                        // Command unknown
                        *offset += cmdSize;
                       break;
                    }
                    break;
                default:
                    // Command unknown
                    *offset += cmdSize;
                    break;
                }
                break;
            default:
                // Command unknown
                *offset += cmdSize;
                break;
            }
        }

        if ((retVal == ARCOMMANDS_DECODER_OK) &&
           (*offset < multisetEnd))
        {
            cmdSize = ARCOMMANDS_ReadWrite_Read16FromBuffer (buffer, buffLen, offset, &error);
            if (error == 1)
            {
                retVal = ARCOMMANDS_DECODER_ERROR_NOT_ENOUGH_DATA;
            } // No else --> Do not modify retVal if read went fine
        }
    }
    return retVal;
}

